# z53-undo: reverses z53-pass-trace-TEMP exactly (b -> a). Run in pwx. Rerun-safe (skips files without z53).
pairs = [('src/wasm/evtloop.cpp', [('static bool s_paintThisPass = true;\nstatic double s_lastPaintMs = 0;\n', 'static bool s_paintThisPass = true;\nstatic double s_lastPaintMs = 0;\n#include <string>   // z53\nint wxz53User = 0, wxz53Timer = 0, wxz53Refresh = 0, wxz53RefreshSkipped = 0, wxz53GlPaint = 0, wxz53Paint = 0;\nstatic std::string s_z53; static double s_z53Since = 0;\n'), ('            const double nowMs = emscripten_get_now();\n            if (s_paintThisPass || nowMs - s_lastPaintMs > 50)   // z50\n            {\n                wxTheApp->Paint();\n                s_lastPaintMs = nowMs;\n            }\n            s_paintThisPass = true;\n', '            const double nowMs = emscripten_get_now();\n            if (s_paintThisPass || nowMs - s_lastPaintMs > 50)   // z50\n            {\n                wxTheApp->Paint();\n                s_lastPaintMs = nowMs;\n            }\n            {   // z53\n                char rec[64]; int n = snprintf(rec, sizeof rec, " %c", s_paintThisPass ? \'F\' : \'I\');\n                if (wxz53User) n += snprintf(rec + n, sizeof rec - n, "u%d", wxz53User);\n                if (wxz53Timer) n += snprintf(rec + n, sizeof rec - n, "t%d", wxz53Timer);\n                if (wxz53Refresh) n += snprintf(rec + n, sizeof rec - n, "r%d", wxz53Refresh);\n                if (wxz53RefreshSkipped) n += snprintf(rec + n, sizeof rec - n, "x%d", wxz53RefreshSkipped);\n                if (wxz53GlPaint) n += snprintf(rec + n, sizeof rec - n, "p%d", wxz53GlPaint);\n                if (wxz53Paint) n += snprintf(rec + n, sizeof rec - n, "P%d", wxz53Paint);\n                s_z53 += rec; wxz53User = wxz53Timer = wxz53Refresh = wxz53RefreshSkipped = wxz53GlPaint = wxz53Paint = 0;\n                if (nowMs - s_z53Since > 3000)\n                {\n                    if (s_z53Since > 0) emscripten_console_logf("wx: passes%s", s_z53.c_str());\n                    s_z53.clear(); s_z53Since = nowMs;\n                }\n            }\n            s_paintThisPass = true;\n')]), ('src/wasm/app.cpp', [('        const bool press = it->first == 2;\n        std::function<void()> handler = std::move(it->second);\n', '        const bool press = it->first == 2;\n        { extern int wxz53User, wxz53Timer; (it->first ? wxz53User : wxz53Timer)++; }   // z53\n        std::function<void()> handler = std::move(it->second);\n')]), ('src/wasm/window.cpp', [('    //printf("Refresh: %p %d %d\\n", this, IsShown(), IsFrozen());\n    if (!IsShown() || IsFrozen())\n    {\n        return;\n    }\n\n    Invalidate(true);\n', '    //printf("Refresh: %p %d %d\\n", this, IsShown(), IsFrozen());\n    const bool z53gl = wxString(GetClassInfo()->GetClassName()).Contains("GLCanvas");   // z53\n    if (!IsShown() || IsFrozen())\n    {\n        if (z53gl) { extern int wxz53RefreshSkipped; wxz53RefreshSkipped++; }\n        return;\n    }\n    if (z53gl) { extern int wxz53Refresh; wxz53Refresh++; }\n\n    Invalidate(true);\n'), ('    wxPaintEvent paintEvent(this);\n    HandleWindowEvent(paintEvent);\n}\n', '    { extern int wxz53GlPaint, wxz53Paint; wxz53Paint++; if (wxString(GetClassInfo()->GetClassName()).Contains("GLCanvas")) wxz53GlPaint++; }   // z53\n    wxPaintEvent paintEvent(this);\n    HandleWindowEvent(paintEvent);\n}\n')])]
for path, ps in pairs:
    s = open(path).read()
    if 'z53' not in s: print('no z53 in', path); continue
    for a, b in ps:
        assert s.count(b) == 1, (path, b[:50], s.count(b)); s = s.replace(b, a)
    open(path, 'w').write(s); print('z53 undone in', path, 'left:', s.count('z53'))
